from pathlib import Path
import re

p=Path('index.html')
s=p.read_text(encoding='utf-8')

def rep(old,new,label):
    global s
    if old not in s:
        raise SystemExit(f'bloco não encontrado: {label}')
    s=s.replace(old,new,1)

def sub(pattern,new,label,flags=re.S):
    global s
    rx=re.compile(pattern,flags)
    s2,n=rx.subn(lambda _m:new,s,count=1)
    if n!=1:
        raise SystemExit(f'bloco regex não encontrado/ambíguo: {label} ({n})')
    s=s2

