# Processamento de imagem + renderização da configuração PDF.
sub(r'''    function renderAdminPdfSettings\(\)\{.*?\n    \}\n\n    function updateAdminDaysAvailable''', '''    async function processAdminPdfLogo(file){\n      if(!file) return;\n      if(!String(file.type||'').startsWith('image/')) return toast('Selecione uma imagem válida para a logo.');\n      if(file.size>4*1024*1024) return toast('A imagem da logo deve ter no máximo 4 MB.');\n      const objectUrl=URL.createObjectURL(file);\n      try{\n        const image=await new Promise((resolve,reject)=>{\n          const img=new Image();\n          img.onload=()=>resolve(img);\n          img.onerror=()=>reject(new Error('Imagem inválida'));\n          img.src=objectUrl;\n        });\n        const maxWidth=520, maxHeight=180;\n        const scale=Math.min(1,maxWidth/image.naturalWidth,maxHeight/image.naturalHeight);\n        const width=Math.max(1,Math.round(image.naturalWidth*scale));\n        const height=Math.max(1,Math.round(image.naturalHeight*scale));\n        const canvas=document.createElement('canvas');\n        canvas.width=width; canvas.height=height;\n        const ctx=canvas.getContext('2d');\n        ctx.fillStyle='#ffffff';\n        ctx.fillRect(0,0,width,height);\n        ctx.drawImage(image,0,0,width,height);\n        const data=canvas.toDataURL('image/jpeg',.82);\n        adminPdfLogoDraft={data,width,height,name:file.name||'logo'};\n        el('adminPdfLogoEnabled').checked=true;\n        renderAdminPdfSettings();\n        saveAdminDraft();\n        toast('Logo adicionada. Ela aparecerá somente se a opção estiver marcada.');\n      }catch(error){\n        console.error('Falha ao processar logo:',error);\n        toast('Não foi possível processar esta imagem. Tente PNG, JPG ou WEBP.');\n      }finally{\n        URL.revokeObjectURL(objectUrl);\n      }\n    }\n\n    function renderAdminPdfSettings(){\n      const note=el('adminPdfThemeNote');\n      const theme=el('adminPdfTheme')?.value||'premium_masculino';\n      const enabled=Boolean(el('adminPdfButtonEnabled')?.checked);\n      if(note) note.textContent=`Modelo selecionado: ${ADMIN_PDF_THEME_LABELS[theme]||'Premium Masculino'}. O visual é independente do formato do cronograma.`;\n      ['adminPdfButtonText','adminPdfButtonUrl','adminPdfButtonPosition'].forEach(id=>{\n        const field=el(id);\n        if(field) field.disabled=!enabled;\n      });\n      const logoEnabled=Boolean(el('adminPdfLogoEnabled')?.checked);\n      const status=el('adminPdfLogoStatus');\n      if(status){\n        status.textContent=adminPdfLogoDraft.data\n          ? `${logoEnabled?'Logo ativada':'Logo carregada, mas desativada'}: ${adminPdfLogoDraft.name||'imagem selecionada'}.`\n          : 'Nenhuma logo selecionada. O PDF será gerado sem logo.';\n      }\n      const remove=el('adminPdfLogoRemoveBtn');\n      if(remove) remove.disabled=!adminPdfLogoDraft.data;\n    }\n\n    function updateAdminDaysAvailable''','render/process logo')

