needle="""    function pdfApplySelectedTheme(){\n      const key=state.adminPersonalization?.pdfTheme||state.adminPdfTheme||'premium_masculino';\n      const preset=PDF_THEME_PRESETS[key]||PDF_THEME_PRESETS.premium_masculino;\n      PDF_COLORS={...preset.colors};\n      return preset;\n    }\n\n"""
insert=needle+"""    function pdfLogoSettings(){\n      const data=state.adminPersonalization||{};\n      return {\n        enabled:Boolean(data.pdfLogoEnabled??state.adminPdfLogoEnabled),\n        data:data.pdfLogoData||state.adminPdfLogoData||'',\n        width:Number(data.pdfLogoWidth||state.adminPdfLogoWidth)||0,\n        height:Number(data.pdfLogoHeight||state.adminPdfLogoHeight)||0\n      };\n    }\n\n    function pdfHasLogo(){\n      const logo=pdfLogoSettings();\n      return Boolean(logo.enabled&&logo.data&&logo.width>0&&logo.height>0);\n    }\n\n    function pdfLogoAsset(){\n      const logo=pdfLogoSettings();\n      if(!logo.enabled||!logo.data||!logo.width||!logo.height) return null;\n      const match=String(logo.data).match(/^data:image\\/jpeg;base64,(.+)$/);\n      if(!match) return null;\n      try{\n        const decoded=atob(match[1]);\n        return {binary:decoded,width:logo.width,height:logo.height};\n      }catch{return null;}\n    }\n\n    function pdfDrawOptionalLogo(commands){\n      if(!pdfHasLogo()) return;\n      const logo=pdfLogoSettings();\n      const {width,height,margin}=PDF_PAGE;\n      const maxWidth=92, maxHeight=42;\n      const scale=Math.min(maxWidth/logo.width,maxHeight/logo.height);\n      const drawWidth=Math.max(1,logo.width*scale);\n      const drawHeight=Math.max(1,logo.height*scale);\n      const x=width-margin-drawWidth;\n      const y=height-66+(42-drawHeight)/2;\n      commands.push(`q\\n${pdfNumber(drawWidth)} 0 0 ${pdfNumber(drawHeight)} ${pdfNumber(x)} ${pdfNumber(y)} cm\\n/Logo Do\\nQ`);\n    }\n\n"""
rep(needle,insert,'pdf logo helpers')

