# Calendário por dias: exatamente dois dias grandes por página, A4 vertical.
sub(r'''    function pdfPrepareDaysStyle\(\)\{.*?\n    \}\n\n    function pdfPrepareByStyle''', '''    function pdfPrepareDaysStyle(){\n      const tasksByDate=new Map();\n      pdfSortedTasks().forEach(task=>{\n        if(!task.date) return;\n        if(!tasksByDate.has(task.date)) tasksByDate.set(task.date,[]);\n        tasksByDate.get(task.date).push(task);\n      });\n      let dates=state.adminGenerated?pdfAdminCalendarDates():[];\n      if(!dates.length) dates=[...tasksByDate.keys()].sort().map(dateFromKey).filter(Boolean);\n      const days=dates.map((date,index)=>({\n        key:localDateKey(date),\n        date,\n        planIndex:index,\n        tasks:tasksByDate.get(localDateKey(date))||[]\n      }));\n      const pages=[];\n      for(let i=0;i<days.length;i+=2) pages.push({items:days.slice(i,i+2)});\n      return pages.length?pages:[{items:[]}];\n    }\n\n    function pdfCalendarActivityText(task){\n      return String(task.activity||'Atividade de estudo').replace(/^(?:Teoria|Exercícios|Revisão)\\s*-\\s*/i,'');\n    }\n\n    function pdfBuildDaysStylePage(page,pageIndex,pageCount){\n      const commands=[];\n      const labels=page.items.map(day=>day.planIndex+1);\n      const suffix=labels.length===2?`DIAS ${labels[0]} E ${labels[1]}`:(labels.length?`DIA ${labels[0]}`:'CALENDÁRIO');\n      const chrome=pdfDrawStyleChrome(commands,pageIndex,pageCount,`CALENDÁRIO POR QUANTIDADE DE DIAS · ${suffix}`);\n      const {width,margin}=PDF_PAGE;\n      const top=chrome.bodyTop-6;\n      const bottom=chrome.bodyBottom+4;\n      const gap=12;\n      const panelHeight=(top-bottom-gap)/2;\n      const panelWidth=width-margin*2;\n      const totalDays=state.adminPlanDays||state.adminPersonalization?.planDays||page.items.length;\n\n      page.items.forEach((day,index)=>{\n        const panelTop=top-index*(panelHeight+gap);\n        const panelBottom=panelTop-panelHeight;\n        const simulation=day.tasks.some(task=>String(task.type||'').toLowerCase().includes('simulado'));\n        pdfRect(commands,margin,panelBottom,panelWidth,panelHeight,simulation?PDF_COLORS.pendingSoft:PDF_COLORS.white,simulation?PDF_COLORS.gold:PDF_COLORS.line,simulation?1.1:.8);\n        pdfRect(commands,margin,panelTop-38,panelWidth,38,simulation?PDF_COLORS.gold:PDF_COLORS.navy,null,0);\n        const dayName=DAYS[(day.date.getDay()+6)%7]||'';\n        pdfText(commands,margin+12,panelTop-16,`${dayName.toUpperCase()} · ${day.date.toLocaleDateString('pt-BR')}`,11.5,true,simulation?PDF_COLORS.navy:PDF_COLORS.white);\n        pdfText(commands,width-margin-100,panelTop-16,`DIA ${day.planIndex+1} DE ${totalDays}`,9.2,true,simulation?PDF_COLORS.navy:PDF_COLORS.white,'right',88);\n\n        const contentTop=panelTop-54;\n        if(!day.tasks.length){\n          pdfText(commands,margin+16,contentTop,'SEM ESTUDO PROGRAMADO',13,true,PDF_COLORS.muted);\n          pdfText(commands,margin+16,contentTop-23,'Descanso / dia livre',10.5,false,PDF_COLORS.muted);\n          return;\n        }\n        if(simulation){\n          const task=day.tasks[0];\n          pdfText(commands,margin+16,contentTop,'SIMULADO',14,true,PDF_COLORS.goldDark);\n          pdfText(commands,margin+16,contentTop-24,pdfWrapText(task.activity||task.subject,panelWidth-32,12,2,true)[0],12,true,PDF_COLORS.text);\n          pdfText(commands,margin+16,contentTop-47,`${task.start||''}${task.end?`–${task.end}`:''}`,10.5,true,PDF_COLORS.muted);\n          if(task.notes) pdfText(commands,margin+16,contentTop-69,pdfWrapText(task.notes,panelWidth-32,9.5,2,false)[0],9.5,false,PDF_COLORS.muted);\n          return;\n        }\n\n        const bodyHeight=panelHeight-56;\n        const count=Math.max(1,day.tasks.length);\n        const rowHeight=Math.max(10.8,Math.min(18,bodyHeight/count));\n        const font=rowHeight<12?7.8:(rowHeight<14?8.5:9.2);\n        const timeWidth=62;\n        const subjectWidth=155;\n        const activityX=margin+16+timeWidth+subjectWidth;\n        const activityWidth=panelWidth-32-timeWidth-subjectWidth;\n        let y=contentTop;\n        day.tasks.forEach((task,taskIndex)=>{\n          if(y<panelBottom+9) return;\n          const time=`${task.start||''}${task.end?`–${task.end}`:''}`;\n          const subject=`${task.subject||'Estudo'} · ${task.type||'Estudo'}`;\n          pdfText(commands,margin+16,y,pdfWrapText(time,timeWidth-5,font,1,true)[0],font,true,PDF_COLORS.muted);\n          pdfText(commands,margin+16+timeWidth,y,pdfWrapText(subject,subjectWidth-7,font,1,true)[0],font,true,PDF_COLORS.navy);\n          pdfText(commands,activityX,y,pdfWrapText(pdfCalendarActivityText(task),activityWidth,font,1,false)[0],font,false,PDF_COLORS.text);\n          if(taskIndex<day.tasks.length-1) pdfLine(commands,margin+16,y-rowHeight+3,width-margin-16,y-rowHeight+3,PDF_COLORS.line,.35);\n          y-=rowHeight;\n        });\n      });\n\n      if(page.items.length===1){\n        const emptyTop=top-(panelHeight+gap);\n        pdfRect(commands,margin,emptyTop-panelHeight,panelWidth,panelHeight,PDF_COLORS.soft,PDF_COLORS.line,.5);\n        pdfText(commands,margin+16,emptyTop-34,'FIM DO PERÍODO PLANEJADO',11,true,PDF_COLORS.muted);\n      }\n      return {content:commands.join('\\n'),button:chrome.button};\n    }\n\n    function pdfPrepareByStyle''','two-day calendar')

