insert="""      el('adminPdfTheme').addEventListener('change',()=>{ renderAdminPdfSettings(); saveAdminDraft(); });\n      el('adminPdfLogoEnabled').addEventListener('change',()=>{ renderAdminPdfSettings(); saveAdminDraft(); });\n      el('adminPdfLogoUpload').addEventListener('change',event=>{\n        const file=event.target.files?.[0];\n        if(file) processAdminPdfLogo(file);\n        event.target.value='';\n      });\n      el('adminPdfLogoRemoveBtn').addEventListener('click',()=>{\n        adminPdfLogoDraft={data:'',width:0,height:0,name:''};\n        el('adminPdfLogoEnabled').checked=false;\n        renderAdminPdfSettings();\n        saveAdminDraft();\n        toast('Logo removida. O PDF será gerado sem logo.');\n      });\n      el('adminPdfButtonEnabled').addEventListener('change',()=>{ renderAdminPdfSettings(); saveAdminDraft(); });\n"""
rep(needle,insert,'logo events')

